    S03: { id: 'S03', metric: 'Integraciones fallidas por 100 intentos', unit: 'fallos', baseline: 14, controls: ['Integración directa a SDK', 'Adapter con contract tests y timeout', 'Duplicar el bloque if por consumidor'], efficacy: [0, .65, -.15], tradeoffs: ['Acoplamiento a proveedor', 'Mantenimiento de adaptadores', 'Multiplica defectos por copia'], assumption: 'Tasas ilustrativas; no se ejecutan SDKs' },
    S04: { id: 'S04', metric: 'Pruebas que requieren infraestructura', unit: 'tests', baseline: 80, controls: ['Dominio importa ORM y web', 'Puertos y tests de dominio aislado', 'Crear un ORM diferente'], efficacy: [0, .75, .10], tradeoffs: ['Pruebas lentas y frágiles', 'Se requiere mapa de dependencias', 'Cambia herramienta sin cambiar acoplamiento'], assumption: '80 casos de referencia ilustrativos' },
    S05: { id: 'S05', metric: 'Cambios entre equipos por regla', unit: 'coordinaciones', baseline: 12, controls: ['Modelo global compartido', 'Bounded contexts + traductor de contratos', 'Duplicar tablas sin contratos'], efficacy: [0, .58, .05], tradeoffs: ['Gobierno centralizado continuo', 'Requiere acuerdos semánticos', 'Inconsistencias no controladas'], assumption: 'Coordinaciones artificiales por tipo de cambio' },
    S06: { id: 'S06', metric: 'Sobreventas en 100 carreras concurrentes', unit: 'casos', baseline: 30, controls: ['Read-modify-write sin lock', 'Versionado optimista o UPDATE condicional', 'Aumentar TTL del cache'], efficacy: [0, 1, -.08], tradeoffs: ['Riesgo de stock negativo', 'Conflictos requieren reintento seguro', 'Cache no garantiza atomicidad'], assumption: 'Modelo lógico de 100 carreras, no banco de datos concurrente' },
