    S08: { id: 'S08', metric: 'Dependencias síncronas en ruta crítica', unit: 'saltos', baseline: 9, controls: ['Mantener todas las llamadas', 'Separar tareas opcionales mediante eventos', 'Crear más servicios síncronos'], efficacy: [0, .55, -.45], tradeoffs: ['Latencia acumulativa', 'Complejidad de entrega eventual', 'Más red y fallos encadenados'], assumption: 'Nueve saltos lógicos en una operación ficticia' },
    S09: { id: 'S09', metric: 'Cargos repetidos en 100 pedidos', unit: 'cargos', baseline: 25, controls: ['Cobrar cada webhook', 'Idempotencia persistida + outbox', 'Reintentar el cargo 3 veces sin clave'], efficacy: [0, 1, -1], tradeoffs: ['No protege duplicados', 'Requiere índice y estado durable', 'Multiplica duplicados'], assumption: '25 webhooks repetidos; usar banco S09 para detalle de outbox' },
    S10: { id: 'S10', metric: 'Lecturas interpretadas erróneamente', unit: 'errores', baseline: 30, controls: ['Leer réplica y fallar al instante', 'Read-your-writes y estado pendiente', 'Forzar cache global por 1 hora'], efficacy: [0, .90, -.20], tradeoffs: ['Falsos errores', 'Mayor costo de lectura consistente', 'Se agrava el desfase visible'], assumption: 'Modelo hipotético de 30 lecturas atrasadas' },
    S11: { id: 'S11', metric: 'Solicitudes descartadas en un pico', unit: 'solicitudes', baseline: 2000, controls: ['Retry sin límites', 'Backpressure + réplica y cola acotada', 'Ignorar límite de cola'], efficacy: [-.50, .85, .10], tradeoffs: ['Aumenta la avalancha de peticiones', 'Costo de capacidad y tradeoff de latencia', 'Riesgo de crecimiento de memoria'], assumption: 'Carga sintética, usar el banco de colas S11 para mayor detalle' },
    S12: { id: 'S12', metric: 'Accesos indebidos en 100 intentos', unit: 'accesos', baseline: 50, controls: ['Confiar en X-Role', 'Autorización por recurso y tenant', 'Esconder el botón de UI'], efficacy: [0, 1, .02], tradeoffs: ['IDOR y elevación de privilegios', 'Requiere política y pruebas negativas', 'La UI no es frontera de seguridad'], assumption: '100 intentos artificiales, no pentest real' },
